async def run_bots():
    db.init_db()
    _v144_zhurnal("база готова, собираем ботов")

    # UA-V144 · обработчик диагностики живёт внутри этого процесса
    try:
        import kadry_diagnostiki as _kd144
        _v144_zhurnal("обработчик диагностики: поднят" if _kd144.zapustit_iz_run_all()
                      else "обработчик диагностики: уже работает в другом процессе")
    except Exception as _e144:
        _v144_zhurnal("обработчик диагностики НЕ поднят: %r" % _e144)

    apps = []

    # --- Клиентский бот ---
    try:
        import lead_bot
        client_app = lead_bot.build_application()
        if client_app:
            apps.append(("клиентский", client_app))
    except Exception as e:
        logging.error(f"Клиентский бот не собрался: {e}", exc_info=True)

    # --- Внутренний бот ---
    try:
        import team_bot
        team_app = team_bot.build_application()
        if team_app:
            apps.append(("внутренний", team_app))
    except Exception as e:
        logging.error(f"Внутренний бот не собрался: {e}", exc_info=True)

    if not apps:
        logging.error("Ни один бот не запустился. Проверьте файлы с токенами.")
        return

    for name, app in apps:
        await app.initialize()
        await app.start()
        await app.updater.start_polling(drop_pending_updates=False)
        logging.info(f"Запущен бот: {name}")
        _v144_zhurnal("запущен бот: %s" % name)

    logging.info(f"Всего работает ботов: {len(apps)}")
    _v144_zhurnal("всего работает ботов: %d — вход в ожидание" % len(apps))

    try:
        # Держим процесс живым
        while True:
            await asyncio.sleep(3600)
    finally:
        _v144_zhurnal("ВЫХОД из ожидания — боты останавливаются")
        for name, app in apps:
            try:
                await app.updater.stop()
                await app.stop()
                await app.shutdown()
                logging.info(f"Остановлен бот: {name}")
            except Exception as e:
                logging.warning(f"Ошибка остановки {name}: {e}")

def patch_bot_methods():
    """Повторы отправки при обрыве связи."""
    from telegram import Bot
    from telegram.error import TimedOut, NetworkError, RetryAfter

    errors = (TimedOut, NetworkError, RetryAfter)

    # ВАЖНО: ExtBot наследуется от Bot. Если обернуть оба класса,
    # повторы вкладываются друг в друга: 4 попытки превращаются в 16.
    # Поэтому Bot трогаем только там, где ExtBot своего метода не имеет.
    ext = None
    try:
        from telegram.ext import ExtBot
        ext = ExtBot
    except Exception:
        ext = None

    n = 0
    for name in TEXT_METHODS + MEDIA_METHODS + SILENT_METHODS:
        target = None
        if ext is not None and name in ext.__dict__:
            target = ext
        elif name in Bot.__dict__:
            target = Bot
        if target is None:
            continue
        orig = target.__dict__.get(name)
        if orig is None or getattr(orig, "_ns_wrapped", False):
            continue
        if name in SILENT_METHODS:
            setattr(target, name, _wrap_silent(orig))
        else:
            setattr(target, name, _wrap_send(orig, name in MEDIA_METHODS, errors))
        n += 1
    log.info("защищено методов отправки: %d", n)

def patch_error_handlers():
    """Сетевые таймауты не уходят владельцу как «Сбой во внутреннем боте»."""
    from telegram.ext import Application
    from telegram.error import TimedOut, NetworkError

    orig = Application.add_error_handler
    if getattr(orig, "_ns_wrapped", False):
        return

    def filtered(callback):
        @functools.wraps(callback)
        async def inner(update, context):
            err = getattr(context, "error", None)
            if isinstance(err, (TimedOut, NetworkError)):
                log.warning("сетевая ошибка не показана владельцу: %r", err)
                return
            return await callback(update, context)

        inner._ns_filtered = True
        return inner

    @functools.wraps(orig)
    def inner(self, callback, block=True, *args, **kwargs):
        if not getattr(callback, "_ns_filtered", False):
            callback = filtered(callback)
        try:
            return orig(self, callback, block, *args, **kwargs)
        except TypeError:
            return orig(self, callback)

    inner._ns_wrapped = True
    Application.add_error_handler = inner
    log.info("фильтр сетевых ошибок включён")

def patch_register_hook():
    """Регистрируем /pokaz на том приложении, где токен CRM-бота."""
    from telegram.ext import Application

    team_token = "<redacted>"
    path = os.path.join(BASE, "team_token.txt")
    if os.path.exists(path):
        try:
            with open(path, "r", encoding="utf-8") as fh:
                team_token = fh.read().strip()
        except Exception:
            team_token = "<redacted>"

    orig = Application.initialize
    if getattr(orig, "_ns_wrapped", False):
        return

    @functools.wraps(orig)
    async def inner(self, *args, **kwargs):
        result = await orig(self, *args, **kwargs)
        try:
            register_token(self)          # смена токена работает в обоих ботах
            token = getattr(getattr(self, "bot", None), "token", "")
            if not team_token or token == team_token:
                register_pokaz(self)
        except Exception as e:
            log.warning("не удалось подключить /pokaz: %r", e)
        return result

    inner._ns_wrapped = True
    Application.initialize = inner

def apply_all():
    ok = True
    for func in (
        patch_request_timeouts,
        patch_bot_methods,
        patch_error_handlers,
        patch_register_hook,
        patch_card_html_budget,
        patch_download_cache,
    ):
        try:
            func()
        except Exception as e:
            ok = False
            log.warning("не удалось применить %s: %r", func.__name__, e)
    return ok

def _zhivoy_token(znachenie):
    """Проверяет токен у Telegram. Ничего не отправляет, только спрашивает."""
    if not znachenie:
        return False
    try:
        import urllib.request
        import json as _json
        adres = "https://api.telegram.org/bot%s/getMe" % znachenie
        with urllib.request.urlopen(adres, timeout=20) as otvet:
            return bool(_json.loads(otvet.read().decode("utf-8")).get("ok"))
    except Exception as e:
        log.warning("токен не проверился: %r", e)
        return None          # непонятно — считаем, что жив

def _zapis(tip, sek, info):
    try:
        if os.path.exists(ZHURNAL) and os.path.getsize(ZHURNAL) > PREDEL and tip not in ("COMMIT_FAIL", "ZAPUSK"):
            return
        with open(ZHURNAL, "a", encoding="utf-8") as f:
            f.write(time.strftime("%Y-%m-%d %H:%M:%S") + "\t" + str(tip).ljust(14) + "\t"
                    + ("%8.2f" % sek) + "\tPID" + str(os.getpid()) + "\t"
                    + threading.current_thread().name + "\t" + str(info) + "\n")
    except Exception:
        pass
